   206→            max-height: none;
   207→            overflow-y: visible;
   208→        }
   209→
   210→        .count-badge {
   211→            background: #30363d;
   212→            color: #8b949e;
   213→            font-size: 11px;
   214→            padding: 2px 8px;
   215→            border-radius: 10px;
   216→        }
   217→
   218→        .back-btn {
   219→            padding: 10px 16px;
   220→            background: #21262d;
