  1080→                        summary = obj.summary;
  1081→                    } else if (obj.type === 'user' || obj.type === 'assistant') {
  1082→                        if (!agentId && obj.agentId) agentId = obj.agentId;
  1083→                        // Skip "Warmup" messages
