  1176→        function renderMessage(msg, showTools) {
  1177→            const time = msg.timestamp ? new Date(msg.timestamp).toLocaleTimeString(undefined, {hour: '2-digit', minute: '2-digit'}) : '';
  1178→
  1179→            // Check if this is a tool_result message (comes as type: "user" but is really tool output)
  1180→            const isToolResult = msg.type === 'user' &&
  1181→                Array.isArray(msg.message?.content) &&
  1182→                msg.message.content.some(c => c.type === 'tool_result');
