  1188→            const isContinuation = msg.type === 'user' &&
  1189→                typeof msg.message?.content === 'string' &&
  1190→                msg.message.content.startsWith('This session is being continued from a previous conversation');
  1191→
  1192→            const role = isToolResult ? 'tool' : ((isMeta || isContinuation) ? 'system' : (msg.type === 'user' ? 'user' : (msg.type === 'assistant' ? 'assistant' : 'system')));
  1193→
  1194→            let content = '';
  1195→
  1196→            // Handle system messages (different structure)
