  1200→                if (msg.hookInfos && msg.hookInfos.length > 0) {
  1201→                    parts.push(`Hooks: ${msg.hookInfos.map(h => h.command).join(', ')}`);
  1202→                }
  1203→                if (msg.stopReason) parts.push(`Stop: ${msg.stopReason}`);
  1204→                if (msg.level) parts.push(`Level: ${msg.level}`);
  1205→                content = escapeHtml(parts.join(' | ') || 'System event');
  1206→                // Show hook output/errors if present
  1207→                if (msg.hookErrors && msg.hookErrors.length > 0) {
  1208→                    content += '<div class="hook-output">' + msg.hookErrors.map(e => escapeHtml(e)).join('<hr>') + '</div>';
  1209→                }
  1210→            } else if (msg.message) {
  1211→                if (typeof msg.message.content === 'string') {
  1212→                    content = escapeHtml(msg.message.content);
  1213→                } else if (Array.isArray(msg.message.content)) {
