  1221→                                : c.source.url;
  1222→                            return `<div class="image-container"><img class="message-image" src="${src}" alt="Image"></div>`;
  1223→                        } else if (c.type === 'tool_use' && showTools) {
  1224→                            return renderToolUse(c);
  1225→                        } else if (c.type === 'tool_result' && showTools) {
