  1239→            if (msg.gitBranch) tooltipData.branch = msg.gitBranch;
  1240→            if (msg.version) tooltipData.version = msg.version;
  1241→            if (msg.isSidechain !== undefined) tooltipData.sidechain = msg.isSidechain;
  1242→            if (msg.cwd) tooltipData.cwd = msg.cwd;
