// Initialize from URL or load projects
(async () => {
    const { project, session, message } = loadFromUrl();
    await loadProjectsData();
    if (project) {
        const fullProject = project.startsWith('-Users') ? project : getFullProjectName(project);
        if (session) {
            currentProject = fullProject;
            currentMessage = message || null;
            await loadProjectSessions(fullProject, false);
            const filePath = `data/projects/${fullProject}/${session}.jsonl`;
            await loadConversation(filePath, false);
            // Small delay to ensure DOM is fully rendered
            if (currentMessage) {
                setTimeout(() => scrollToMessage(currentMessage), 100);
            }
        } else {
            await loadProjectSessions(fullProject, false);
        }
    } else {
        // Auto-load latest session from the first project
        if (projects.length > 0) {
            const firstProject = projects[0];
            currentProject = firstProject.name;

            // Get sessions for the first project
            let sessions;
            if (indexData) {
                const projectData = indexData.projects.find(p => p.name === firstProject.name);
                sessions = projectData ? projectData.sessions : [];
            }

            // Find the first main session (not an agent session)
            const mainSessions = sessions ? sessions.filter(s => !s.agentId) : [];
            if (mainSessions.length > 0) {
                const latestSession = mainSessions[0];
                await loadProjectSessions(firstProject.name, false);
                await loadConversation(latestSession.path, false);
                updateUrl();
            } else {
                await loadProjectSessions(firstProject.name, false);
            }
        } else {
            renderProjectsList();
        }
    }
})();

